package com.agriconnect.model; import jakarta.persistence.*; @Entity @Table(name="users") public class AppUser { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String fullName; @Column(unique=true,nullable=false) private String email; private String password; @Enumerated(EnumType.STRING) private Role role; private String location; public enum Role{FARMER,VENDOR,BUYER} public Long getId(){return id;} public void setId(Long v){id=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} }